import{c as d,Q as i,j as l,m as a,g as e,n as r}from"./chunks/framework.BPKcPtvA.js";const b=JSON.parse('{"title":"LMM 多模态感知与对齐","description":"","frontmatter":{},"headers":[],"relativePath":"03-large-models/multimodal-alignment.md","filePath":"03-large-models/multimodal-alignment.md"}'),n={name:"03-large-models/multimodal-alignment.md"};function o(s,t,h,c,m,u){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="lmm-多模态感知与对齐" tabindex="-1">LMM 多模态感知与对齐 <a class="header-anchor" href="#lmm-多模态感知与对齐" aria-label="Permalink to &quot;LMM 多模态感知与对齐&quot;">​</a></h1><blockquote><p>Vision Transformer 与跨模态对齐 —— 让模型「看见」世界</p></blockquote><h2 id="从-llm-到-lmm" tabindex="-1">从 LLM 到 LMM <a class="header-anchor" href="#从-llm-到-lmm" aria-label="Permalink to &quot;从 LLM 到 LMM&quot;">​</a></h2><p>大型多模态模型（Large Multimodal Model, LMM）将 LLM 的文本理解能力扩展至视觉、音频等多模态输入，使模型能够「看见」并理解图像、视频内容。</p><h3 id="核心架构范式" tabindex="-1">核心架构范式 <a class="header-anchor" href="#核心架构范式" aria-label="Permalink to &quot;核心架构范式&quot;">​</a></h3><p>绝大多数 LMM 采用「视觉编码器 + 连接器 + LLM」的架构：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>图像 → [Vision Encoder] → [Connector/Projector] → [LLM] → 文本输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>模型</th><th>视觉编码器</th><th>连接器</th><th>LLM 基座</th></tr></thead><tbody><tr><td>LLaVA</td><td>CLIP ViT-L</td><td>MLP 投影</td><td>LLaMA/Vicuna</td></tr><tr><td>Qwen-VL</td><td>ViT-G</td><td>Cross-Attention Resampler</td><td>Qwen</td></tr><tr><td>InternVL</td><td>InternViT</td><td>像素洗牌投影</td><td>InternLM</td></tr><tr><td>GPT-4V</td><td>闭源</td><td>闭源</td><td>GPT-4</td></tr></tbody></table><hr><h2 id="vision-transformer-vit" tabindex="-1">Vision Transformer (ViT) <a class="header-anchor" href="#vision-transformer-vit" aria-label="Permalink to &quot;Vision Transformer (ViT)&quot;">​</a></h2><h3 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h3><p>将图像的 Patch 序列类比为 NLP 中的 Token 序列：</p><ol><li>图像被切分为固定大小的 Patches（如 $16\\times16$）</li><li>每个 Patch 被展开为向量，经线性投影得到 Patch Embedding</li><li>加入位置编码后送入标准 Transformer</li></ol><h3 id="对比-cnn" tabindex="-1">对比 CNN <a class="header-anchor" href="#对比-cnn" aria-label="Permalink to &quot;对比 CNN&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>CNN</th><th>ViT</th></tr></thead><tbody><tr><td>归纳偏置</td><td>局部性、平移等变性（强）</td><td>弱，完全由数据学习</td></tr><tr><td>数据需求</td><td>中等</td><td>大规模数据</td></tr><tr><td>计算复杂度</td><td>$O(k^2 n)$</td><td>$O(n^2)$（注意力）</td></tr></tbody></table><hr><h2 id="跨模态对齐原理" tabindex="-1">跨模态对齐原理 <a class="header-anchor" href="#跨模态对齐原理" aria-label="Permalink to &quot;跨模态对齐原理&quot;">​</a></h2><p>跨模态对齐的目标是让视觉特征和文本特征在同一个语义空间中具有一致的表示。</p><h3 id="clip-对比学习" tabindex="-1">CLIP 对比学习 <a class="header-anchor" href="#clip-对比学习" aria-label="Permalink to &quot;CLIP 对比学习&quot;">​</a></h3><p>CLIP 是 LMM 最核心的对齐基础模型，通过对比学习将图像-文本对映射到共享嵌入空间：</p>',20),e("p",null,[r("$$ \\mathcal{L}"),e("em",{i:""},"{\\text{CLIP}} = -\\frac{1}{2N}\\sum"),r("\\left[\\log\\frac{\\exp(s_{ii}/\\tau)}{\\sum_j\\exp(s_{ij}/\\tau)} + \\log\\frac{\\exp(s_{ii}/\\tau)}{\\sum_j\\exp(s_{ji}/\\tau)}\\right] $$")],-1),a('<p>其中 $s_{ij}$ 是第 $i$ 张图像与第 $j$ 段文本的余弦相似度。</p><h3 id="连接器设计" tabindex="-1">连接器设计 <a class="header-anchor" href="#连接器设计" aria-label="Permalink to &quot;连接器设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>连接器类型</th><th>描述</th><th>代表模型</th></tr></thead><tbody><tr><td>Linear / MLP</td><td>最简单，直接投影</td><td>LLaVA-1.5</td></tr><tr><td>Q-Former</td><td>可学习的 Query 向量压缩视觉 Token</td><td>BLIP-2</td></tr><tr><td>Cross-Attention Resampler</td><td>用可学习 Query 交叉关注视觉特征</td><td>Qwen-VL</td></tr><tr><td>Pixel Shuffle</td><td>像素重排减少 Token 数</td><td>InternVL 2</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">关键设计权衡</p><p>连接器需要在<strong>视觉信息保留</strong>与<strong>Token 压缩效率</strong>之间取得平衡。视觉特征通常产生数百至数千个 Token，而 LLM 的 Context 窗口昂贵，因此高效的视觉 Token 压缩是 LMM 工程化的核心挑战。</p></div><h3 id="高分辨率策略" tabindex="-1">高分辨率策略 <a class="header-anchor" href="#高分辨率策略" aria-label="Permalink to &quot;高分辨率策略&quot;">​</a></h3><p>高分辨率对 OCR、图表理解等任务至关重要，常用方法：</p><ul><li><strong>Dynamic Resolution</strong>：将图像切分为多个子图分别编码后拼接</li><li><strong>AnyRes</strong>：支持任意分辨率输入，自适应分块</li><li><strong>Tile-based Encoding</strong>：按固定尺寸 Tile 切分，适合文档场景</li></ul><hr><h2 id="多模态训练策略" tabindex="-1">多模态训练策略 <a class="header-anchor" href="#多模态训练策略" aria-label="Permalink to &quot;多模态训练策略&quot;">​</a></h2><h3 id="两阶段训练" tabindex="-1">两阶段训练 <a class="header-anchor" href="#两阶段训练" aria-label="Permalink to &quot;两阶段训练&quot;">​</a></h3><ol><li><strong>预对齐阶段</strong>：冻结视觉编码器和 LLM，仅训练连接器，在大量图文对上快速对齐模态</li><li><strong>指令微调阶段</strong>：解冻 LLM（或全部参数），在多模态指令数据上微调，提升指令遵循与推理能力</li></ol>',11)])])}const L=d(n,[["render",o]]);export{b as __pageData,L as default};
